-- Catalog entries needed by the two photographed Melanie routines.
-- Safe to re-run: names are unique, existing descriptions are preserved,
-- and only missing descriptions are filled in.
INSERT INTO exercise_catalog (name, muscle_group, equipment, instructions)
VALUES
  ('Hip thrust', 'Glúteos', 'Barra',
   'Apoya la parte alta de la espalda en un banco y coloca la barra sobre la cadera con protección. Con los pies firmes, empuja el suelo y eleva la pelvis hasta alinear hombros, cadera y rodillas. Aprieta los glúteos arriba sin arquear la espalda; baja con control.'),
  ('Elevación de pantorrillas en máquina', 'Pantorrillas', 'Máquina',
   'Coloca la parte delantera de los pies en la plataforma y ajusta el apoyo sobre los hombros. Baja los talones hasta sentir un estiramiento cómodo y elévalos al máximo sin rebotar. Mantén una pausa breve arriba y controla el descenso.'),
  ('Jalón al pecho con agarre supino', 'Espalda', 'Poleas',
   'Sujeta la barra con las palmas hacia ti y las manos aproximadamente al ancho de los hombros. Mantén el torso estable y lleva los codos hacia abajo mientras acercas la barra a la parte alta del pecho. Regresa lentamente sin balancearte.'),
  ('Remo a un brazo con mancuerna', 'Espalda', 'Mancuernas',
   'Apoya una mano y una rodilla en un banco, manteniendo la espalda neutra. Con la otra mano, lleva la mancuerna hacia la cadera y acerca el codo al torso. Baja con control, completa las repeticiones y cambia de lado.'),
  ('Extensión de piernas en máquina', 'Cuádriceps', 'Máquina',
   'Ajusta el respaldo y coloca el rodillo delante de los tobillos. Extiende las rodillas sin bloquearlas, aprieta los cuádriceps y baja lentamente hasta la posición inicial. Usa un recorrido cómodo y evita impulsarte.'),
  ('Patada de mula para glúteos', 'Glúteos', 'Otro',
   'Colócate en la máquina o posición indicada, con el abdomen firme y la espalda neutra. Empuja el talón hacia atrás y arriba desde la cadera, contrayendo el glúteo sin girar la pelvis ni arquear la zona lumbar. Regresa despacio y repite por lado.'),
  ('Press California con barra', 'Tríceps', 'Barra',
   'Acuéstate en un banco y toma la barra con agarre cerrado. Flexiona los codos y dirige la barra hacia la parte alta del pecho o detrás de la cabeza, manteniéndolos cerca del cuerpo. Extiende los brazos para volver sin abrir los codos.'),
  ('Aperturas de pecho en polea baja', 'Pecho', 'Poleas',
   'Coloca las poleas abajo y toma una agarradera en cada mano. Con una ligera flexión de codos y el torso estable, junta las manos al frente describiendo un arco. Aprieta el pecho y vuelve lentamente hasta un estiramiento cómodo.'),
  ('Sentadilla hack', 'Cuádriceps', 'Máquina',
   'Acomoda hombros y espalda contra el respaldo, con los pies firmes en la plataforma. Flexiona cadera y rodillas siguiendo la dirección de los pies, hasta un rango cómodo. Empuja la plataforma para subir sin bloquear las rodillas y mantén la espalda apoyada.'),
  ('Curl femoral sentado', 'Femoral', 'Máquina',
   'Ajusta el asiento y los rodillos para que el eje coincida con la rodilla. Flexiona las rodillas llevando los talones hacia abajo y atrás, sin despegar la cadera del asiento. Regresa lentamente hasta estirar las piernas de forma cómoda.'),
  ('Aducción de cadera en máquina', 'Pierna completa', 'Máquina',
   'Siéntate con la espalda apoyada y coloca las piernas contra los cojines exteriores. Junta las piernas de forma controlada, sin impulso, y aprieta la parte interna de los muslos. Regresa despacio hasta el estiramiento cómodo.'),
  ('Elevación de pantorrillas sentado', 'Pantorrillas', 'Máquina',
   'Apoya la punta de los pies en la plataforma y coloca el rodillo sobre los muslos, cerca de las rodillas. Baja los talones con control y elévalos al máximo sin rebotar. Mantén el movimiento en los tobillos.'),
  ('Face pull en polea', 'Hombros', 'Poleas',
   'Ajusta la cuerda a la altura de la cara y sujétala con ambas manos. Tira hacia la frente separando las manos y llevando los codos hacia afuera y atrás. Mantén el torso quieto y vuelve lentamente.'),
  ('Curl de bíceps doble en polea baja', 'Bíceps', 'Poleas',
   'Colócate entre las poleas bajas y toma las agarraderas con los brazos extendidos. Flexiona ambos codos llevando las manos hacia los hombros, sin mover el torso. Baja lentamente y evita que los hombros se adelanten.'),
  ('Curl alterno de bíceps de pie con mancuernas', 'Bíceps', 'Mancuernas',
   'De pie, sostén una mancuerna en cada mano con los codos junto al torso. Flexiona un codo llevando la mancuerna al hombro, sin balancearte; baja con control y alterna los brazos.'),
  ('Elevación lateral con mancuernas', 'Hombros', 'Mancuernas',
   'De pie, sostén las mancuernas a los lados con los codos ligeramente flexionados. Eleva los brazos hacia los lados hasta la altura de los hombros sin encogerlos. Baja despacio y evita usar impulso.'),
  ('Press militar con mancuernas', 'Hombros', 'Mancuernas',
   'Sentada o de pie, inicia con las mancuernas a la altura de los hombros y las muñecas alineadas. Empuja hacia arriba sin arquear la espalda y baja con control hasta la posición inicial.'),
  ('Press de banca con barra', 'Pecho', 'Barra',
   'Acuéstate con los pies apoyados y la espalda estable en el banco. Baja la barra hacia el centro del pecho con los codos ligeramente por debajo de los hombros; empuja hasta extender los brazos sin bloquearlos. Usa un peso que controles.'),
  ('Cristo en máquina (peck deck)', 'Pecho', 'Máquina',
   'Ajusta el asiento para que los brazos queden a la altura del pecho. Junta las almohadillas al frente con una ligera flexión de codos, sin encoger los hombros. Regresa lentamente hasta sentir un estiramiento cómodo.'),
  ('Extensión de tríceps con barra recta en polea', 'Tríceps', 'Poleas',
   'Sujeta la barra con los codos pegados al torso. Extiende los antebrazos hacia abajo hasta acercar las manos a los muslos, sin mover los hombros. Regresa con control hasta flexionar los codos.'),
  ('Extensión de tríceps sobre la cabeza con mancuerna (copa)', 'Tríceps', 'Mancuernas',
   'Sostén una mancuerna sobre la cabeza con ambas manos y los codos apuntando al frente. Flexiona los codos para bajar la mancuerna detrás de la cabeza; extiende los brazos sin abrirlos ni arquear la espalda.'),
  ('Fondos en paralelas', 'Tríceps', 'Peso corporal',
   'Sujétate de las barras y estabiliza los hombros. Flexiona los codos para bajar el cuerpo hasta un rango cómodo y empuja para volver arriba. Mantén el movimiento controlado y no fuerces el hombro.'),
  ('Desplante con barra', 'Pierna completa', 'Barra',
   'Coloca la barra de forma estable sobre la espalda alta. Da un paso al frente y flexiona ambas rodillas, manteniendo el torso firme y la rodilla delantera alineada con el pie. Empuja con el pie delantero para volver y alterna lados.'),
  ('Prensa a 45 grados', 'Cuádriceps', 'Máquina',
   'Apoya la espalda y la pelvis en el respaldo, colocando los pies en la plataforma. Baja el carro hasta un rango cómodo sin despegar la cadera; empuja con todo el pie y evita bloquear las rodillas.'),
  ('Press inclinado con mancuernas', 'Pecho', 'Mancuernas',
   'Ajusta el banco a una inclinación moderada y sostén las mancuernas a los lados del pecho. Empuja hacia arriba siguiendo una trayectoria estable y baja lentamente hasta un estiramiento cómodo.'),
  ('Press francés con barra Z', 'Tríceps', 'Barra',
   'Acuéstate en un banco y sostén la barra Z sobre el pecho con los brazos extendidos. Flexiona los codos llevando la barra hacia la frente o detrás de la cabeza; extiende los codos manteniendo los brazos superiores estables.'),
  ('Jalón al pecho', 'Espalda', 'Poleas',
   'Sujeta la barra con las manos algo más abiertas que los hombros. Mantén el pecho elevado y lleva los codos hacia abajo para acercar la barra a la parte alta del pecho. Regresa lentamente sin balancear el torso.'),
  ('Curl de bíceps en máquina', 'Bíceps', 'Máquina',
   'Ajusta el asiento para que los codos queden alineados con el eje de la máquina. Flexiona los codos acercando las manos a los hombros y aprieta los bíceps. Regresa lentamente sin despegar los brazos del apoyo.'),
  ('Patada de glúteo en polea', 'Glúteos', 'Poleas',
   'Coloca una tobillera en la polea baja y sujétate para mantener el equilibrio. Lleva la pierna hacia atrás desde la cadera, sin arquear la espalda, y contrae el glúteo. Vuelve lentamente y cambia de lado.'),
  ('Sentadilla búlgara con mancuernas', 'Cuádriceps', 'Mancuernas',
   'Coloca el empeine de un pie sobre un banco detrás de ti y adelanta el otro pie. Desciende flexionando la pierna delantera con el torso estable y la rodilla alineada con el pie. Empuja el suelo para subir y completa ambos lados.'),
  ('Peso muerto rumano con mancuernas', 'Femoral', 'Mancuernas',
   'Sostén las mancuernas delante de los muslos y flexiona ligeramente las rodillas. Lleva la cadera hacia atrás mientras bajas las pesas cerca de las piernas, manteniendo la espalda neutra. Extiende la cadera para volver arriba.'),
  ('Prensa horizontal', 'Cuádriceps', 'Máquina',
   'Apoya la espalda y la pelvis en el respaldo y coloca los pies al ancho de cadera. Flexiona las rodillas hasta un rango cómodo y empuja la plataforma sin bloquearlas. Mantén el movimiento uniforme.'),
  ('Curl femoral acostado', 'Femoral', 'Máquina',
   'Acuéstate boca abajo y ajusta el rodillo justo por encima de los tobillos. Flexiona las rodillas acercando los talones a los glúteos sin levantar la pelvis. Baja con control hasta estirar cómodamente.'),
  ('Extensión acostado con barra Z', 'Tríceps', 'Barra',
   'Acuéstate en el banco y sostén la barra Z sobre el pecho. Flexiona los codos bajando la barra detrás de la cabeza sin mover los brazos superiores; extiende los codos para regresar con control.'),
  ('Pullover en polea alta', 'Espalda', 'Poleas',
   'De pie frente a una polea alta, sujeta la barra o cuerda con los brazos casi extendidos. Lleva las manos hacia los muslos mediante un arco, manteniendo el torso estable y activando la espalda. Vuelve despacio.'),
  ('Remo en banco romano con polea baja', 'Espalda', 'Poleas',
   'Siéntate estable en el banco romano y toma el agarre conectado a la polea baja. Lleva los codos hacia atrás y junta suavemente los omóplatos, manteniendo la espalda neutra. Extiende los brazos lentamente.'),
  ('Extensión de tríceps con cuerda', 'Tríceps', 'Poleas',
   'Sujeta la cuerda en la polea alta con los codos junto al torso. Extiende los brazos hacia abajo y separa los extremos de la cuerda al final del movimiento. Regresa despacio sin mover los hombros.')
ON CONFLICT (name) DO UPDATE
SET instructions = COALESCE(NULLIF(exercise_catalog.instructions, ''), EXCLUDED.instructions),
    active = true;
